static const char WEB_INDEX_HTML[] =
    "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>OLDSKULL — Palco (versão web interativa)</title>\n<style>\n  @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;600;700&family=Playfair+Display:wght@500;700&display=swap');\n  :root{ --ouro:#f3c969; --ouro-claro:#f7dd9a; --painel:rgba(14,11,8,.94); --borda:#f3c969; --f1:'Cinzel',serif; --f2:'Playfair Display','Cinzel',Georgia,serif; }\n  *{margin:0;padding:0;box-sizing:border-box; -webkit-tap-highlight-color:transparent}\n  html,body{width:100%;height:100%;overflow:hidden;background:#000;font-family:var(--f1);color:#f0e0c0}\n\n  /* VIDEO PREENCHE A TELA TODA */\n  #vid{position:fixed;inset:0;width:100%;height:100%;object-fit:cover;z-index:0}\n  #vidStill{position:fixed;inset:0;width:100%;height:100%;object-fit:cover;z-index:0;display:none}\n\n  /* ---- MENU SUPERIOR ---- */\n  .menubar{position:fixed;top:0;left:0;right:0;display:flex;gap:8px;padding:10px 14px;z-index:50;flex-wrap:wrap;background:linear-gradient(to bottom,rgba(5,5,7,.85),rgba(5,5,7,0))}\n  .mbtn{background:rgba(10,8,6,.78);border:1px solid var(--ouro);color:var(--ouro-claro);padding:7px 14px;font-size:13px;font-family:var(--f1);font-weight:600;letter-spacing:.16em;text-transform:uppercase;cursor:pointer;border-radius:6px;transition:.2s;text-shadow:0 1px 2px rgba(0,0,0,.6)}\n  .mbtn:hover,.mbtn.ativo{background:var(--ouro);color:#0a0a08}\n  #bank{position:fixed;top:12px;right:14px;z-index:50;font-size:11px;letter-spacing:.15em;color:var(--ouro);background:rgba(10,8,6,.65);padding:5px 10px;border:1px solid var(--ouro);border-radius:6px}\n\n  /* ---- CARROSSEL EM V (1 frente + 2 atras) ---- */\n  .carrossel{position:fixed;left:0;right:0;top:0;bottom:0;z-index:3}\n  .amp{position:absolute;transition:left .5s cubic-bezier(.4,0,.2,1),top .5s,width .5s,opacity .5s;cursor:pointer}\n  .amp img{width:100%;height:100%;object-fit:contain;poin"
    "ter-events:none}\n  .amp .nome{display:none}\n\n  /* ---- PEDAIS NA BASE (8 slots, drag-drop) ---- */\n  .pedals{position:fixed;left:0;right:0;bottom:0;height:220px;display:grid;grid-template-columns:repeat(8,minmax(105px,1fr));\n          gap:4px;align-content:center;justify-items:center;\n          background:linear-gradient(to top,rgba(6,5,4,.96),rgba(6,5,4,.12),transparent);z-index:4;padding:0 2%;box-sizing:border-box}\n  .pedal-slot{border:none;border-radius:10px;display:flex;align-items:center;justify-content:center;\n          width:100%;height:100%;overflow:visible;transition:.2s;cursor:default}\n  .pedal-slot.dragover{box-shadow:0 0 12px var(--ouro)}\n  .pedal-slot .pedal{display:flex;align-items:center;justify-content:center;width:115%;height:115%;border-radius:8px;transition:.2s;cursor:pointer;position:relative}\n  .pedal-slot .pedal img{width:100%;height:100%;object-fit:cover;pointer-events:none}\n  .pedal-slot .pedal.on{box-shadow:none}\n  .pedal-slot .pedal:not(.on){opacity:.5;filter:brightness(.55)saturate(.7);transition:.2s}\n  .pedal-slot .pedal.dragging{opacity:.3}\n\n  /* ---- SETAS ---- */\n  .seta{position:fixed;top:42%;transform:translateY(-50%);width:48px;height:48px;border-radius:50%;background:rgba(20,16,10,.85);border:2px solid var(--ouro);color:var(--ouro);font-size:24px;cursor:pointer;z-index:35;display:flex;align-items:center;justify-content:center}\n  #esq{left:22px}#dir{right:22px}\n  .seta:hover{background:var(--ouro);color:#0a0a08}\n\n  /* ---- PAINEIS (sem sobreposicao de texto) ---- */\n  .painel{position:fixed;top:58px;right:16px;width:min(340px,86vw);max-height:calc(100vh - 90px);overflow-y:auto;\n          background:var(--painel);border:2px solid var(--ouro);border-radius:12px;padding:16px;z-index:60;display:none;box-shadow:0 0 40px rgba(0,0,0,.75)}\n  .painel.aberto{display:block;animation:ap .25s ease}\n  @keyframes ap{from{opacity:0;transform:translateX(14px)}to{opacity:1;transform:none}}\n  /* ---- SUBMENUS COLAPSÁVEIS ----"
    " */\n  .submenu-header{position:relative;margin:10px 0 6px 0;padding:8px 10px;background:rgba(14,11,8,.55);border:1px solid var(--ouro);border-radius:8px;cursor:pointer;font-size:13px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--ouro-claro);\n    display:flex;align-items:center;justify-content:space-between}\n  .submenu-header:hover{background:rgba(243,201,105,.1)}\n  .submenu-header .sub-arrow{transition:transform .2s; color:var(--ouro)}\n  .submenu-header .sub-arrow.aberto{transform:rotate(90deg)}\n  .submenu-body{max-height:0;overflow:hidden;transition:max-height .25s ease;list-style:none;margin:0 0 8px 0;padding:0;border-left:1px solid rgba(243,201,105,.1)}\n  .submenu-body.aberto{max-height:500px}\n  .submenu-item{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 6px 8px 18px;border-bottom:1px solid rgba(243,201,105,.08);cursor:pointer;font-size:13px}\n  .submenu-item:hover{background:rgba(243,201,105,.06)}\n  .submenu-item .k{letter-spacing:.06em;text-transform:uppercase;color:#e6d3a8}\n  .submenu-item .v{color:var(--ouro)}\n  .painel h3{font-size:14px;letter-spacing:.2em;color:var(--ouro-claro);font-weight:700;text-transform:uppercase;border-bottom:1px solid var(--ouro);padding-bottom:8px;margin-bottom:12px}\n  .item{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 6px;border-bottom:1px solid rgba(243,201,105,.15);cursor:pointer;font-size:13px;flex-wrap:wrap}\n  .item:hover{background:rgba(243,201,105,.12)}\n  .item .k{letter-spacing:.08em;text-transform:uppercase;color:#e6d3a8}\n  .item .v{color:var(--ouro)}\n  .fechar{position:absolute;top:8px;right:10px;border:none;background:none;color:var(--ouro);font-size:20px;cursor:pointer;line-height:1}\n  .toggle{width:38px;height:20px;border-radius:10px;background:#333;position:relative;flex:0 0 auto;cursor:pointer;transition:.2s}\n  .toggle.on{background:var(--ouro)}\n  .toggle::after{content:'';position:absolute;top:2p"
    "x;left:3px;width:16px;height:16px;border-radius:50%;background:#faf6ea;transition:.2s}\n  .toggle.on::after{left:19px}\n  .fpsrow{display:flex;gap:6px;flex-wrap:wrap}\n  .hint{font-size:11px;color:#baa;margin-top:12px;line-height:1.5;border-top:1px solid rgba(243,201,105,.2);padding-top:10px}\n  #aviso{position:fixed;bottom:92px;left:50%;transform:translateX(-50%);background:rgba(10,8,6,.92);border:1px solid var(--ouro);color:var(--ouro);padding:8px 16px;border-radius:20px;font-size:12px;z-index:70;opacity:0;transition:.3s;pointer-events:none;letter-spacing:.08em;white-space:nowrap}\n</style>\n<script>\n/* BASE automatica: no AP old_skull (192.168.4.1) ou em http://<ip-do-esp>/ na rede local */\nvar BASE = '';\ntry {\n  var h = location.hostname;\n  if (!h || h === '192.168.4.1') {\n    BASE = 'http://192.168.4.1';\n  } else {\n    BASE = location.origin || ('http://' + h + (location.port ? ':' + location.port : ''));\n  }\n} catch (e) { BASE = ''; }\n</script>\n</head>\n<body>\n  <video id=\"vid\" muted loop playsinline></video>\n  <img id=\"vidStill\" src=\"assets/fundo_palco.jpg\" alt=\"\">\n\n  <div class=\"menubar\">\n    <button class=\"mbtn\" data-m=\"presets\">Presets</button>\n    <button class=\"mbtn\" data-m=\"pedais\">Pedais</button>\n    <button class=\"mbtn\" data-m=\"amp\">Amp</button>\n    <button class=\"mbtn\" data-m=\"rede\">Rede</button>\n    <button class=\"mbtn\" data-m=\"skin\">Skin</button>\n    <button class=\"mbtn\" data-m=\"sistema\">Sistema</button>\n    <button class=\"mbtn\" data-m=\"midi\">MIDI</button>\n  </div>\n  <div id=\"bank\">BANK 01 · SCENE 01</div>\n\n  <div id=\"esq\" class=\"seta\">‹</div><div id=\"dir\" class=\"seta\">›</div>\n\n  <div class=\"carrossel\" id=\"carrossel\">\n    <div class=\"amp\" id=\"amp0\"><img src=\"assets/amp_lonestar.png\" alt=\"Lonestar\"><div class=\"nome\">LONE STAR</div></div>\n    <div class=\"amp\" id=\"amp1\"><img src=\"assets/amp_soldano.png\" alt=\"Soldano\"><div class=\"nome\">SOLDANO</div></"
    "div>\n    <div class=\"amp\" id=\"amp2\"><img src=\"assets/amp_jp2c.png\" alt=\"JP2C\"><div class=\"nome\">JP-2C</div></div>\n  </div>\n\n  <div class=\"pedals\" id=\"pedalStrip\"></div>\n\n  <div class=\"painel\" id=\"p-presets\">\n    <button class=\"fechar\">×</button><h3>Presets (Bancos)</h3>\n    <div class=\"item\" data-preset=\"1\"><span class=\"k\">Banco 1 · Clean</span><span class=\"v\">►</span></div>\n    <div class=\"item\" data-preset=\"2\"><span class=\"k\">Banco 2 · Crunch</span><span class=\"v\">►</span></div>\n    <div class=\"item\" data-preset=\"3\"><span class=\"k\">Banco 3 · Lead</span><span class=\"v\">►</span></div>\n    <div class=\"item\" data-preset=\"4\"><span class=\"k\">Banco 4 · Custom</span><span class=\"v\">►</span></div>\n    <div class=\"item\" data-preset=\"5\"><span class=\"k\">Banco 5 · Custom</span><span class=\"v\">►</span></div>\n    <div class=\"hint\">Aplica o banco e muda o amp central.</div>\n  </div>\n  <div class=\"painel\" id=\"p-pedais\">\n    <button class=\"fechar\">×</button><h3>Pedais</h3>\n    <div id=\"pedalCheckboxes\" style=\"margin:6px 0\"></div>\n    <div class=\"hint\">Marque os pedais para exibi-los na base. Só OVERDRIVE + CHORUS disponíveis.</div>\n  </div>\n  <div class=\"painel\" id=\"p-amp\">\n    <button class=\"fechar\">×</button><h3>Amp</h3>\n    <div class=\"item\" data-amp=\"0\"><span class=\"k\">Trocar Amp →</span></div>\n    <div class=\"hint\">Troca o amp em destaque (LoneStar → Soldano → JP-2C).</div>\n  </div>\n  <div class=\"painel\" id=\"p-rede\">\n    <button class=\"fechar\">×</button><h3>Rede (WiFi)</h3>\n    <div class=\"item\"><span class=\"k\">Status</span><span class=\"v\" id=\"redeStatus\">Conectando…</span></div>\n    <div class=\"item\"><span class=\"k\">SSID</span><span class=\"v\">oldskull</span></div>\n    <div class=\"item\"><span class=\"k\">AP Ligado</span><div class=\"toggle on\" id=\"aptog\"></div></div>\n  </div>\n  <div class=\"painel\" id=\"p-skin\">\n    <button class=\""
    "fechar\">×</button><h3>Skin · Fundo</h3>\n    <div id=\"skinList\"></div>\n    <div class=\"hint\">Escolha a visualização: Vídeo (loop do palco) ou um dos fundos fixos. A composição (amps em V + pedais + menus) permanece igual.</div>\n  </div>\n  <div class=\"painel\" id=\"p-sistema\">\n    <button class=\"fechar\">×</button><h3>Sistema</h3>\n    <div class=\"item\"><span class=\"k\">Vídeo</span><div class=\"toggle on\" id=\"vidTog\"></div></div>\n    <div class=\"item\"><span class=\"k\">Veloc. vídeo</span>\n      <div class=\"fpsrow\">\n        <button class=\"mbtn\" data-fps=\"8\">8</button><button class=\"mbtn ativo\" data-fps=\"24\">24</button><button class=\"mbtn\" data-fps=\"40\">40</button>\n      </div></div>\n  </div>\n\n  <div class=\"painel\" id=\"p-midi\">\n    <button class=\"fechar\">×</button><h3>MIDI</h3>\n    <div class=\"item\"><span class=\"k\">Canal MIDI</span><span class=\"v\">1</span></div>\n    <div class=\"item\"><span class=\"k\">Clock Sync</span><span class=\"v\">OFF</span></div>\n    <div class=\"submenu-header\" data-sub=\"scenes\"><span>Scenes</span><span class=\"sub-arrow\">▼</span></div>\n    <div class=\"submenu-body\" id=\"sub-scenes\">\n      <div class=\"submenu-item\" data-scene=\"1\"><span class=\"k\">Scene 1 · Clean</span><span class=\"v\">►</span></div>\n      <div class=\"submenu-item\" data-scene=\"2\"><span class=\"k\">Scene 2 · Crunch</span><span class=\"v\">►</span></div>\n      <div class=\"submenu-item\" data-scene=\"3\"><span class=\"k\">Scene 3 · Lead</span><span class=\"v\">►</span></div>\n      <div class=\"submenu-item\" data-scene=\"4\"><span class=\"k\">Scene 4 · Custom</span><span class=\"v\">►</span></div>\n    </div>\n    <div class=\"hint\">Envie mensagens MIDI para trocar de cena e amp. Clique em Scenes para expandir.</div>\n  </div>\n\n  <div id=\"aviso\"></div>\n\n<script>\nconst AMPS=[\n  {nome:'LONE STAR', img:'assets/amp_lonestar.png', w:606, h:330},\n  {nome:'SOLDANO',   img:'assets/amp_soldano.png', w"
    ":330, h:330},\n  {nome:'JP-2C',     img:'assets/amp_jp2c.png',    w:330, h:330},\n];\nconst PEDAIS=[{nome:'OVERDRIVE',img:'overdrive'},{nome:'CHORUS',img:'chorus'},{nome:'DELAY',img:'delay'}];\nlet idxCentral=0, videoOn=true, fps=24;\nconst $=s=>document.querySelector(s);\nconst ampEls=[$('#amp0'),$('#amp1'),$('#amp2')];\nconst vid=$('#vid'), still=$('#vidStill');\n\n// Carrossel em V: 1 na frente (embaixo, grande) + 2 atras (superior esq/dir, cobertos)\nfunction layoutCarrossel(){\n  // replica fiel do firmware: tela virtual 800x480, posicoes exatas do app_main.c\n  const W=innerWidth, H=innerHeight;\n  const CW=800, CH=480;\n  const S=Math.min(W/CW,H/CH);\n  const offX=(W-CW*S)/2, offY=(H-CH*S)/2;\n  ampEls.forEach((el,i)=>{\n    let d=(i-idxCentral+3)%3; if(d===2)d=-1;   // d: -1 esq, 0 frente, +1 dir\n    let cx,cy;\n    if(d===0){ cx=400; cy=245; }\n    else if(d===-1){ cx=140; cy=140; }\n    else { cx=660; cy=140; }\n    const w=AMPS[i].w, h=AMPS[i].h;            // tamanho nativo (sem escalar o amp)\n    const L=(cx-w/2), T=(cy-150);              // posicao top-left no espaco 800x480\n    el.style.left=(offX+L*S)+'px';\n    el.style.top=(offY+T*S)+'px';\n    el.style.width=(w*S)+'px';\n    el.style.height=(h*S)+'px';\n    el.style.zIndex=(d===0?5:2);\n    el.style.opacity=(d===0?1:0.5);\n  });\n  $('#bank').textContent='BANK 01 · SCENE 01';\n}\nfunction proximo(dir){ idxCentral=(idxCentral+dir+3)%3; layoutCarrossel(); piscar('AMP · '+AMPS[idxCentral].nome); }\n$('#esq').onclick=()=>proximo(-1); $('#dir').onclick=()=>proximo(+1);\nampEls[0].onclick=()=>proximo(-1); ampEls[2].onclick=()=>proximo(+1); ampEls[1].onclick=()=>proximo(+1);\n\nfunction carregaVideo(){ vid.src='assets/video_palco.mp4'; vid.playbackRate=fps/24; vid.play().catch(()=>{});\n  vid.ontimeupdate=()=>{ if(vid.currentTime>=vid.duration){vid.currentTime=0;vid.play().catch(()=>{});} }; }\n$('#vidTog').onclick=()=>{ videoOn=!videoOn; $('#vidTog').classList.toggle('on',videoOn);\n  vid.style.displ"
    "ay=videoOn?'block':'none'; still.style.display=videoOn?'none':'block'; piscar('Vídeo '+(videoOn?'LIGADO':'PAUSADO')); };\ndocument.querySelectorAll('[data-fps]').forEach(b=>b.onclick=()=>{ fps=+b.dataset.fps;\n  document.querySelectorAll('[data-fps]').forEach(x=>x.classList.remove('ativo')); b.classList.add('ativo');\n  vid.playbackRate=fps/24; piscar('Velocidade '+fps+' fps'); });\n$('#aptog').onclick=()=>{ $('#aptog').classList.toggle('on'); piscar('WiFi AP '+($('#aptog').classList.contains('on')?'LIGADO':'DESLIGADO')); };\n\n// ---- PEDAIS: 8 slots, checkboxes no painel, nomes editáveis, drag-drop ----\nconst strip=$('#pedalStrip');\nconst SLOT_COUNT=8;\nconst slots=[];\nlet draggedPedal=null;\nfunction makePedal(p){\n  const d=document.createElement('div'); d.className='pedal on'; d.dataset.pedal=p.nome; d._pedal=p; d.draggable=true;\n  d.innerHTML='<img src=\"assets/pedals/'+p.img+'.png\" alt=\"'+p.nome+'\">'; d.title=p.nome;\n  d.addEventListener('dragstart',()=>{ d.classList.add('dragging'); draggedPedal=d; });\n  d.addEventListener('dragend',()=>{ d.classList.remove('dragging'); draggedPedal=null; });\n  d.onclick=()=>{ d.classList.toggle('on'); piscar((d.classList.contains('on')?'ON ':'OFF ')+p.nome); };\n  return d;\n}\nfunction addPedalToSlot(p){\n  for(let i=0;i<SLOT_COUNT;i++){ if(!slots[i].querySelector('.pedal')){ slots[i].appendChild(makePedal(p)); return true; } }\n  piscar('Slots cheios'); return false;\n}\nfunction removeLastOfType(nome){\n  const pedais=document.querySelectorAll('.pedal[data-pedal=\"'+nome+'\"]');\n  if(pedais.length>0) pedais[pedais.length-1].parentElement.removeChild(pedais[pedais.length-1]);\n}\nfor(let s=0;s<SLOT_COUNT;s++){\n  const slot=document.createElement('div'); slot.className='pedal-slot'; slot.dataset.idx=s;\n  slot.addEventListener('dragover',ev=>{ ev.preventDefault(); slot.classList.add('dragover'); });\n  slot.addEventListener('dragleave',()=>slot.classList.remove('dragover'));\n  slot.addEventListener('drop',ev=>"
    "{\n    ev.preventDefault(); slot.classList.remove('dragover');\n    if(!draggedPedal||draggedPedal.parentElement===slot) return;\n    const fromSlot=draggedPedal.parentElement, toPedal=slot.querySelector('.pedal');\n    if(toPedal){ const tp=toPedal._pedal; fromSlot.removeChild(draggedPedal); slot.removeChild(toPedal);\n      slot.appendChild(draggedPedal); fromSlot.appendChild(makePedal(tp)); }\n    else { fromSlot.removeChild(draggedPedal); slot.appendChild(draggedPedal); }\n  });\n  strip.appendChild(slot); slots.push(slot);\n}\n(function setupPedalPanel(){\n  const cb=$('#pedalCheckboxes');\n  const upd=()=>document.querySelectorAll('#pedalCheckboxes .item').forEach((div,i)=>{ const c=document.querySelectorAll('.pedal[data-pedal=\"'+PEDAIS[i].nome+'\"]').length; const s=div.querySelector('.p-count'); if(s) s.textContent=c; });\n  PEDAIS.forEach((p,i)=>{\n    const div=document.createElement('div'); div.className='item';\n    div.innerHTML='<div style=\"display:flex;align-items:center;gap:3px;margin:3px 0\">'+\n      '<input class=\"pedal-name\" type=\"text\" value=\"'+p.nome+'\" style=\"flex:1;font-family:var(--f2);font-size:11px;font-weight:700;text-transform:uppercase;color:var(--ouro-claro);background:rgba(0,0,0,.6);border:1px solid var(--ouro);border-radius:3px;padding:2px 4px;outline:none\">'+\n      '<button class=\"p-add\" style=\"width:20px;height:20px;background:var(--ouro);color:#000;border:none;border-radius:3px;font-weight:700;cursor:pointer\">+</button>'+\n      '<span class=\"p-count\" style=\"font-size:11px;color:var(--ouro-claro);width:20px;text-align:center\">0</span>'+\n      '<button class=\"p-remove\" style=\"width:20px;height:20px;background:var(--ouro);color:#000;border:none;border-radius:3px;font-weight:700;cursor:pointer\">−</button></div>';\n    cb.appendChild(div);\n  div.querySelector('.p-add').onclick=()=>{ if(addPedalToSlot(p)){ piscar(p.nome+' +'); } upd(); };\n    div.querySelector('.p-remove').onclick=()=>{ removeLastOfType(p.nome"
    "); piscar(p.nome+' −'); upd(); };\n  });\n})();\n// Fill all 8 slots with repeating pedais\nfor(let s=0;s<8;s++){ slots[s].appendChild(makePedal(PEDAIS[s%3])); }\n(function updCounts(){ document.querySelectorAll('#pedalCheckboxes .item').forEach((div,i)=>{ const c=document.querySelectorAll('.pedal[data-pedal=\"'+PEDAIS[i].nome+'\"]').length; const s=div.querySelector('.p-count'); if(s) s.textContent=c; }); })();\nfunction fecharTodos(){ document.querySelectorAll('.painel').forEach(p=>p.classList.remove('aberto')); document.querySelectorAll('.mbtn').forEach(b=>b.classList.remove('ativo')); }\ndocument.querySelectorAll('.mbtn[data-m]').forEach(b=>b.onclick=()=>{ const p=$('#p-'+b.dataset.m); const aberto=p.classList.contains('aberto'); fecharTodos();\n  if(!aberto){ p.classList.add('aberto'); b.classList.add('ativo'); } });\ndocument.querySelectorAll('.fechar').forEach(f=>f.onclick=fecharTodos);\ndocument.addEventListener('click',ev=>{ if(!ev.target.closest('.painel')&&!ev.target.closest('.mbtn')) fecharTodos(); });\n\ndocument.querySelectorAll('#p-presets .item').forEach(it=>it.onclick=()=>{ const b=it.dataset.preset;\n  piscar('BANK '+b+' aplicado (CMD'+b+')'); idxCentral=(b-1)%3; layoutCarrossel(); fecharTodos(); });\ndocument.querySelector('#p-amp .item').onclick=()=>{ proximo(+1); fecharTodos(); };\n\n// ---- SKIN / FUNDO ----\nconst SKINS=[\n  {nome:'VÍDEO',    img:null},\n  {nome:'PALCO',    img:'assets/fundo_palco.jpg'},\n  {nome:'ESTÚDIO',  img:'assets/cenario_palco.jpg'},\n  {nome:'STEAMPUNK',img:'assets/palco_steampunk.jpg'},\n];\nconst skinList=$('#skinList');\nSKINS.forEach((s,i)=>{ const it=document.createElement('div'); it.className='item';\n  it.innerHTML='<span class=\"k\">'+s.nome+'</span><span class=\"v\">'+ (i===0?'●':'○') +'</span>';\n  it.onclick=()=>{ // VÍDEO é uma das opções; fundos são as outras\n    document.querySelectorAll('#skinList .v').forEach(v=>v.textContent='○'); it.querySelector('.v').textContent='●';\n    if(s.img){ // fundo fixo\n"
    "      still.src=s.img; videoOn=false; vid.style.display='none'; still.style.display='block';\n      $('#vidTog').classList.remove('on'); piscar('Skin · '+s.nome+' (fundo)');\n    } else {   // vídeo\n      videoOn=true; vid.style.display='block'; still.style.display='none';\n      $('#vidTog').classList.add('on'); vid.play().catch(()=>{}); piscar('Skin · Vídeo');\n    }\n    fecharTodos();\n  };\n  skinList.appendChild(it); });\n\nsetTimeout(()=>$('#redeStatus').textContent='Conectado ✓',1200);\nfunction piscar(t){ const a=$('#aviso'); a.textContent=t; a.style.opacity=1; clearTimeout(a._t); a._t=setTimeout(()=>a.style.opacity=0,1400); }\n\naddEventListener('resize',layoutCarrossel); carregaVideo(); layoutCarrossel();\n\n// ---- SUBMENUS COLAPSÁVEIS (MIDI) ----\ndocument.querySelectorAll('.submenu-header').forEach(h=>{\n  h.addEventListener('click',ev=>{\n    ev.stopPropagation();\n    const body=h.nextElementSibling;\n    const arrow=h.querySelector('.sub-arrow');\n    const open=body.classList.contains('aberto');\n    body.classList.toggle('aberto',!open);\n    arrow.classList.toggle('aberto',!open);\n  });\n});\ndocument.querySelectorAll('.submenu-item[data-scene]').forEach(it=>{\n  it.addEventListener('click',ev=>{\n    ev.stopPropagation();\n    const sc=+it.dataset.scene;\n    idxCentral=(sc-1)%3; layoutCarrossel();\n    piscar('Scene '+sc+' (MIDI)');\n  });\n});\n</script>\n</body>\n</html>\n";

